
class AddPage extends StatefulWidget{final void Function(double,double) onSave;const AddPage({required this.onSave,super.key});@override State<AddPage> createState()=>_AddPageState();}
class _AddPageState extends State<AddPage>{final cap=TextEditingController(text:'10000');final tar=TextEditingController(text:'10');@override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(20),children:[const Header('إضافة بيانات','حدّث رأس مالك وهدفك الشهري'),_Field(label:'رأس المال الحالي',hint:'مثال: 10000',controller:cap,icon:Icons.account_balance_wallet_outlined),const SizedBox(height:16),_Field(label:'نسبة الربح المستهدفة',hint:'مثال: 10',controller:tar,icon:Icons.percent),const SizedBox(height:26),SizedBox(height:54,child:ElevatedButton.icon(onPressed:(){widget.onSave(double.tryParse(cap.text)??10000,double.tryParse(tar.text)??10);},icon:const Icon(Icons.save_outlined),label:const Text('حفظ البيانات',style:TextStyle(fontSize:16)),style:ElevatedButton.styleFrom(backgroundColor:const Color(0xff335cff),foregroundColor:Colors.white,shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(14)))))]);}
