class Stats extends StatelessWidget{final List<MonthResult> months;const Stats({required this.months,super.key});@override Widget build(BuildContext c){final avg=months.map((e)=>e.profit).reduce((a,b)=>a+b)/months.length;return ListView(padding:const EdgeInsets.all(20),children:[const Header('الإحصائيات','تابع تطور أدائك عبر الوقت'),Card(child:Padding(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('أداء 2024',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),const SizedBox(height:20),SizedBox(height:150,child:Row(crossAxisAlignment:CrossAxisAlignment.end,mainAxisAlignment:MainAxisAlignment.spaceAround,children:months.map((m)=>Column(mainAxisAlignment:MainAxisAlignment.end,children:[Container(width:28,height:(m.profit.abs()*7).clamp(8,110),decoration:BoxDecoration(color:m.profit>=0?const Color(0xff335cff):Colors.redAccent,borderRadius:BorderRadius.circular(8))),const SizedBox(height:8),Text(m.name.substring(0,1))])).toList()))])),const SizedBox(height:16),Row(children:[Expanded(child:_Metric(title:'متوسط الربح',value:'${avg.toStringAsFixed(1)}%',icon:Icons.insights,color:const Color(0xff335cff))),const SizedBox(width:12),Expanded(child:_Metric(title:'أشهر ناجحة',value:'${months.where((m)=>m.achieved).length} من ${months.length}',icon:Icons.verified_outlined,color:const Color(0xff00a884)))])]);}}
class Calculator extends StatefulWidget{final double capital;const Calculator({required this.capital,super.key});@override State<Calculator> createState()=>_CalculatorState();}
class _CalculatorState extends State<Calculator>{late final TextEditingController cap=TextEditingController(text:widget.capital.toStringAsFixed(0));final rate=TextEditingController(text:'10');int years=1;@override Widget build(BuildContext c){final principal=double.tryParse(cap.text)??0;final r=(double.tryParse(rate.text)??0)/100;final monthly=years*12;final total=principal*(1+r).toDouble();return ListView(padding:const EdgeInsets.all(20),children:[const Header('حاسبة الأرباح','خطط لنمو رأس مالك مستقبلاً'),_Field(label:'رأس المال',hint:'10000',controller:cap,icon:Icons.savings_outlined),const SizedBox(height:16),_Field(label:'النسبة الشهرية',hint:'10',controller:rate,icon:Icons.percent),const SizedBox(height:18),const Text('المدة',style:TextStyle(fontWeight:FontWeight.bold)),const SizedBox(height:8),Wrap(spacing:8,children:[1,2,3,4,5].map((y)=>ChoiceChip(label:Text('$y ${y==1?'سنة':'سنوات'}'),selected:years==y,onSelected:(_){setState(()=>years=y);},selectedColor:const Color(0xffdfe6ff))).toList()),const SizedBox(height:22),Card(child:Padding(padding:const EdgeInsets.all(22),child:Column(children:[const Text('النتيجة المتوقعة'),const SizedBox(height:8),Text('${total.toStringAsFixed(0)} ر.س',style:const TextStyle(fontSize:32,fontWeight:FontWeight.w800,color:Color(0xff335cff))),Text('بعد $monthly شهراً',style:TextStyle(color:Colors.grey.shade600)),const Divider(height:28),Text('تحتاج إلى ربح ${((principal*r)).toStringAsFixed(0)} ر.س كل شهر',style:const TextStyle(fontWeight:FontWeight.bold))])))]);}}
